<template>
  <div class="pvr-root">
    <!-- Loading overlay -->
    <v-overlay :value="loading" z-index="999">
      <div class="pvr-loader">
        <div class="pvr-loader__dots">
          <span></span><span></span><span></span>
        </div>
        <div class="pvr-loader__text">{{ loadingText }}</div>
      </div>
    </v-overlay>

    <!-- Hero -->
    <header class="pvr-hero" :class="`pvr-hero--self`">
      <div class="pvr-hero__grid"></div>
      <div class="pvr-hero__inner">
        <div class="pvr-hero__breadcrumb">
          <span class="pvr-hero__back" @click="goHome">
            <v-icon size="13" color="rgba(255,255,255,0.6)"
              >mdi-arrow-left</v-icon
            >
            Back
          </span>
          <v-icon size="11" color="rgba(255,255,255,0.3)"
            >mdi-chevron-right</v-icon
          >
          <span>Performance Review</span>
          <v-icon size="11" color="rgba(255,255,255,0.3)"
            >mdi-chevron-right</v-icon
          >
          <span class="pvr-hero__breadcrumb-active">{{ reviewerLabel }}</span>
          <v-spacer></v-spacer>
          <span
            class="pvr-hero__status-badge"
            :class="`pvr-hero__status-badge--${reviewStatus}`"
          >
            {{ reviewStatusLabel }}
          </span>
          <span
            v-if="
              reviewWindowOpen === false &&
                reviewStatus === 'submitted' &&
                !windowClosedDismissed
            "
            class="pvr-hero__window-chip"
          >
            <v-icon size="11" color="#9ca3af">mdi-calendar-lock</v-icon>
            Window closed
            <button
              class="pvr-hero__window-chip-close"
              @click="windowClosedDismissed = true"
              title="Dismiss"
            >
              <v-icon size="10" color="#9ca3af">mdi-close</v-icon>
            </button>
          </span>
        </div>

        <div class="pvr-hero__content">
          <div class="pvr-hero__left">
            <div class="pvr-hero__stage-badge">
              <v-icon size="14" :color="reviewerIconColor">{{
                reviewerIcon
              }}</v-icon>
              Stage {{ reviewerStage }} · {{ reviewerLabel }}
            </div>
            <h1 class="pvr-hero__title">
              {{
                isOwnReview ? "My Performance Review" : staffName + "'s Review"
              }}
            </h1>
            <div class="pvr-hero__meta">
              <div class="pvr-hero__meta-item" v-if="performancePlan">
                <v-icon size="14" color="rgba(255,255,255,0.5)"
                  >mdi-file-document-outline</v-icon
                >
                {{ performancePlan.name }}
              </div>
              <div class="pvr-hero__meta-sep" v-if="performancePlan"></div>
              <div class="pvr-hero__meta-item">
                <v-icon size="14" color="rgba(255,255,255,0.5)"
                  >mdi-calendar</v-icon
                >
                FY {{ reviewWindowTargetFY }}
              </div>
            </div>
          </div>

          <div class="pvr-hero__right">
            <!-- Period selector -->
            <div class="pvr-period-box">
              <div class="pvr-period-box__label">Review Period</div>
              <div class="pvr-period-box__chips">
                <v-chip
                  ><b>Semester {{ reviewPeriodNumber }}</b></v-chip
                >
                <v-chip
                  ><b>{{
                    periods.find((p) => p.code === selectedPeriod).label
                  }}</b></v-chip
                >
              </div>
            </div>

            <!-- Progress ring -->
            <div class="pvr-progress-wrap">
              <div class="pvr-progress-ring">
                <svg width="72" height="72" viewBox="0 0 72 72">
                  <circle
                    cx="36"
                    cy="36"
                    r="28"
                    fill="none"
                    stroke="rgba(255,255,255,0.1)"
                    stroke-width="5"
                  />
                  <circle
                    cx="36"
                    cy="36"
                    r="28"
                    fill="none"
                    stroke="rgba(255,255,255,0.85)"
                    stroke-width="5"
                    stroke-linecap="round"
                    :stroke-dasharray="`${completionPercent * 1.759} 175.9`"
                    transform="rotate(-90 36 36)"
                  />
                </svg>
                <div class="pvr-progress-ring__text">
                  <span class="pvr-progress-ring__pct">{{
                    completionPercent
                  }}</span>
                  <span class="pvr-progress-ring__label">%</span>
                </div>
              </div>
              <div class="pvr-progress-label">
                {{ reviewedCount }} / {{ totalKpisToReview }} KPIs reviewed
              </div>
            </div>
          </div>
        </div>
      </div>
    </header>
    <!-- Review window closed banner — only shown when review is still pending -->
    <v-alert
      v-if="reviewWindowOpen === false && reviewStatus !== 'submitted'"
      type="warning"
      outlined
      dense
      class="pp2-window-alert"
    >
      <v-icon small left>mdi-calendar-lock</v-icon>
      <strong>Review Window Closed.</strong>
      {{ reviewWindowClosedMessage }}
    </v-alert>
    <v-alert type="warning" v-if="hideReview">
      This review is currently not available for you to see
    </v-alert>
    <v-alert type="warning" v-if="supervisorCantReview && isSupervisor">
      Wait for {{ staffName }}'s reviews to be added before you can add
      yours</v-alert
    >
    <v-alert type="warning" v-if="jointCantReview">
      Wait for supervisor's reviews to be added before joint reviews can be
      added</v-alert
    >

    <!-- Body -->
    <div class="pvr-body">
      <!-- No plan state -->
      <div v-if="!loading && !performancePlan" class="pvr-empty-plan">
        <v-icon size="48" color="#d6d3d1">mdi-file-search-outline</v-icon>
        <h3>No Performance Plan Found</h3>
        <p>
          No approved performance plan exists for FY
          {{ reviewWindowTargetFY }}.<br />
          The plan must be submitted and approved before reviews can be added.
        </p>
        <button class="pvr-btn pvr-btn--outline" @click="$router.go(-1)">
          <v-icon left size="14">mdi-arrow-left</v-icon>
          Back to Dashboard
        </button>
      </div>

      <template v-else-if="performancePlan">
        <!-- Validation warning bar -->
        <transition name="pvr-slide">
          <div
            v-if="showValidationBar && !allKpisReviewed"
            class="pvr-validation-bar"
          >
            <v-icon size="16" color="#dc2626">mdi-alert-circle</v-icon>
            <span>
              <strong
                >{{ missingCount }} KPI{{
                  missingCount !== 1 ? "s" : ""
                }}</strong
              >
              still need{{ missingCount === 1 ? "s" : "" }} a review before you
              can submit.
            </span>
            <button
              class="pvr-validation-bar__close"
              @click="showValidationBar = false"
            >
              <v-icon size="14" color="#dc2626">mdi-close</v-icon>
            </button>
          </div>
        </transition>

        <!-- Empty objectives -->
        <div v-if="objectives.length === 0 && !loading" class="pvr-empty-plan">
          <v-icon size="40" color="#d6d3d1">mdi-target</v-icon>
          <h3>No objectives defined</h3>
          <p>The performance plan has no objectives yet.</p>
        </div>

        <!-- ── Objectives ──────────────────────────────────────────────── -->
        <div
          v-for="(obj, objIdx) in objectives.filter(
            (o) => o.adjustmentType !== 'drop',
          )"
          :key="obj.id"
          class="pvr-objective"
        >
          <!-- Objective header -->
          <div
            class="pvr-objective__header"
            :style="{ background: headerBg(objIdx) }"
          >
            <div class="pvr-objective__header-left">
              <span class="pvr-objective__num">{{
                String(objIdx + 1).padStart(2, "0")
              }}</span>
              <div>
                <div class="pvr-objective__title">
                  {{ (obj.replacement || obj).name }}
                </div>
                <div
                  v-if="(obj.replacement || obj).description"
                  class="pvr-objective__desc"
                >
                  {{ (obj.replacement || obj).description }}
                </div>
              </div>
            </div>
            <div class="pvr-objective__header-right">
              <div class="pvr-obj-progress">
                <span class="pvr-obj-progress__count"
                  >{{ objReviewedCount((obj.replacement || obj).id) }}/{{
                    objTotalKpis((obj.replacement || obj).id)
                  }}</span
                >
                <span class="pvr-obj-progress__label">reviewed</span>
              </div>
              <v-icon
                :disabled="hideReview"
                size="20"
                color="rgba(255,255,255,0.75)"
                :class="[
                  'pvr-chevron',
                  {
                    'pvr-rotate':
                      expandedObjectives[(obj.replacement || obj).id],
                  },
                ]"
                style="cursor:pointer"
                @click="toggleObjective((obj.replacement || obj).id)"
                >mdi-chevron-down</v-icon
              >
            </div>
          </div>

          <!-- Expanded body -->
          <v-expand-transition>
            <div
              v-if="expandedObjectives[(obj.replacement || obj).id]"
              class="pvr-objective__body"
            >
              <div
                v-if="getActivities((obj.replacement || obj).id).length === 0"
                class="pvr-no-kpis"
              >
                <v-icon size="14" color="#a8a29e"
                  >mdi-information-outline</v-icon
                >
                No activities defined for this objective
              </div>

              <div
                v-for="(act, actIdx) in getActivities(
                  (obj.replacement || obj).id,
                ).filter((a) => a.adjustmentType !== 'drop')"
                :key="act.id"
                class="pvr-activity"
              >
                <!-- Activity heading -->
                <div class="pvr-activity__heading">
                  <span class="pvr-activity__index"
                    >{{ objIdx + 1 }}.{{ actIdx + 1 }}</span
                  >
                  <div class="pvr-activity__info">
                    <div class="pvr-activity__name">
                      {{ (act.replacement || act).name }}
                    </div>
                    <div
                      v-if="(act.replacement || act).description"
                      class="pvr-activity__desc-small"
                    >
                      {{ (act.replacement || act).description }}
                    </div>
                  </div>
                </div>

                <!-- ── Case A: no sub-activities → KPIs on activity ──── -->
                <template
                  v-if="
                    getSubActivities((act.replacement || act).id).length === 0
                  "
                >
                  <div
                    v-if="getKpis((act.replacement || act).id).length === 0"
                    class="pvr-no-kpis"
                  >
                    <v-icon size="14" color="#a8a29e"
                      >mdi-information-outline</v-icon
                    >
                    No KPIs defined for this activity
                  </div>
                  <div
                    v-for="kpi in getKpis((act.replacement || act).id).filter(
                      (k) => k.adjustmentType !== 'drop',
                    )"
                    :key="kpi.id"
                    class="pvr-kpi-slot"
                    :class="{
                      'pvr-kpi-slot--missing': !kpiReview(
                        (kpi.replacement || kpi).id,
                      ).score,
                    }"
                  >
                    <!-- ── INLINE KPI CARD ── -->
                    <div
                      class="pvr-kpi-card"
                      :class="{
                        'pvr-kpi-card--complete': isKpiComplete(
                          (kpi.replacement || kpi).id,
                        ),
                        'pvr-kpi-card--readonly': reviewStatus === 'submitted',
                      }"
                    >
                      <!-- Missing indicator -->
                      <div
                        v-if="
                          !kpiReview((kpi.replacement || kpi).id).score &&
                            reviewStatus !== 'submitted'
                        "
                        class="pvr-kpi-card__missing-badge"
                      >
                        <v-icon size="11" color="#dc2626"
                          >mdi-alert-circle</v-icon
                        >
                        Review required
                      </div>
                      <!-- Context breadcrumb -->
                      <div class="pvr-kpi-card__context">
                        <span class="pvr-ctx pvr-ctx--obj">{{
                          (obj.replacement || obj).name
                        }}</span>
                        <v-icon size="11" color="#c4b5fd"
                          >mdi-chevron-right</v-icon
                        >
                        <span class="pvr-ctx pvr-ctx--act">{{
                          (act.replacement || act).name
                        }}</span>
                      </div>
                      <!-- KPI identity + score (two-column row) -->
                      <div class="pvr-kpi-card__row">
                        <!-- Left: KPI info + target -->
                        <div class="pvr-kpi-card__info">
                          <div class="pvr-kpi-badge">
                            <v-icon size="11" color="#6366f1"
                              >mdi-chart-bar</v-icon
                            >
                            KPI
                          </div>
                          <div class="pvr-kpi-card__kpi-name">
                            {{ (kpi.replacement || kpi).name }}
                          </div>
                          <div
                            v-if="(kpi.replacement || kpi).description"
                            class="pvr-kpi-card__kpi-desc"
                          >
                            {{ (kpi.replacement || kpi).description }}
                          </div>
                          <div
                            v-if="
                              getTargetForKpi((kpi.replacement || kpi).id) &&
                                getTargetForKpi((kpi.replacement || kpi).id)
                                  .adjustmentType !== 'drop'
                            "
                            class="pvr-kpi-card__target"
                          >
                            <v-icon size="12" color="#059669"
                              >mdi-bullseye-arrow</v-icon
                            >
                            <span class="pvr-kpi-card__target-label"
                              >Target:</span
                            >
                            <span class="pvr-kpi-card__target-name">{{
                              (
                                getTargetForKpi((kpi.replacement || kpi).id)
                                  .replacement ||
                                getTargetForKpi((kpi.replacement || kpi).id)
                              ).name
                            }}</span>
                          </div>
                          <div v-else class="pvr-kpi-card__no-target">
                            <v-icon size="12" color="#a8a29e"
                              >mdi-minus-circle-outline</v-icon
                            >
                            No target set
                          </div>
                        </div>
                        <!-- Right: Score selector -->
                        <div class="pvr-kpi-card__score-panel">
                          <div class="pvr-score-label">
                            {{ reviewerTypeLabel }} Score
                          </div>
                          <div class="pvr-score-btns">
                            <button
                              v-for="opt in scoreOptions"
                              :key="opt.value"
                              class="pvr-score-btn"
                              :class="{
                                'pvr-score-btn--selected':
                                  kpiReview((kpi.replacement || kpi).id)
                                    .score === opt.value,
                              }"
                              :style="
                                kpiReview((kpi.replacement || kpi).id).score ===
                                opt.value
                                  ? {
                                      background: opt.bg,
                                      borderColor: opt.border,
                                      color: opt.color,
                                    }
                                  : {}
                              "
                              :disabled="!canEdit"
                              @click="
                                selectKpiScore(
                                  (kpi.replacement || kpi).id,
                                  opt.value,
                                )
                              "
                            >
                              <span class="pvr-score-btn__num">{{
                                opt.value
                              }}</span>
                              <span class="pvr-score-btn__short">{{
                                opt.short
                              }}</span>
                            </button>
                          </div>
                          <div
                            v-if="kpiReview((kpi.replacement || kpi).id).score"
                            class="pvr-score-selected"
                            :style="{
                              color: scoreOption(
                                kpiReview((kpi.replacement || kpi).id).score,
                              ).color,
                              background: scoreOption(
                                kpiReview((kpi.replacement || kpi).id).score,
                              ).bg,
                            }"
                          >
                            <v-icon
                              size="13"
                              :color="
                                scoreOption(
                                  kpiReview((kpi.replacement || kpi).id).score,
                                ).color
                              "
                              >mdi-check-circle</v-icon
                            >
                            {{
                              scoreOption(
                                kpiReview((kpi.replacement || kpi).id).score,
                              ).label
                            }}
                          </div>
                        </div>
                      </div>
                      <!-- Prior stage reviews -->
                      <div
                        v-if="
                          reviewerCode === 'supervisor' ||
                            reviewerCode === 'joint'
                        "
                        class="pvr-kpi-card__prior-reviews"
                      >
                        <div
                          v-if="selfReviews[(kpi.replacement || kpi).id]"
                          class="pvr-prior-review pvr-prior-review--self"
                        >
                          <div class="pvr-prior-review__header">
                            <v-icon size="13" color="#f97316"
                              >mdi-account-edit</v-icon
                            >
                            <span class="pvr-prior-review__title"
                              >Self Assessment</span
                            >
                            <span
                              class="pvr-prior-review__score"
                              :style="{
                                color: scoreOption(
                                  selfReviews[(kpi.replacement || kpi).id]
                                    .score,
                                ).color,
                                background: scoreOption(
                                  selfReviews[(kpi.replacement || kpi).id]
                                    .score,
                                ).bg,
                              }"
                            >
                              Score:
                              {{
                                selfReviews[(kpi.replacement || kpi).id].score
                              }}
                              &mdash;
                              {{
                                scoreOption(
                                  selfReviews[(kpi.replacement || kpi).id]
                                    .score,
                                ).label
                              }}
                            </span>
                          </div>
                          <div class="pvr-prior-review__comments">
                            {{
                              selfReviews[(kpi.replacement || kpi).id]
                                .comments || "—"
                            }}
                          </div>
                        </div>
                        <div
                          v-if="
                            reviewerCode === 'joint' &&
                              supervisorReviews[(kpi.replacement || kpi).id]
                          "
                          class="pvr-prior-review pvr-prior-review--supervisor"
                        >
                          <div class="pvr-prior-review__header">
                            <v-icon size="13" color="#5eead4"
                              >mdi-clipboard-account</v-icon
                            >
                            <span class="pvr-prior-review__title"
                              >Supervisor Evaluation</span
                            >
                            <span
                              class="pvr-prior-review__score"
                              :style="{
                                color: scoreOption(
                                  supervisorReviews[(kpi.replacement || kpi).id]
                                    .score,
                                ).color,
                                background: scoreOption(
                                  supervisorReviews[(kpi.replacement || kpi).id]
                                    .score,
                                ).bg,
                              }"
                            >
                              Score:
                              {{
                                supervisorReviews[(kpi.replacement || kpi).id]
                                  .score
                              }}
                              &mdash;
                              {{
                                scoreOption(
                                  supervisorReviews[(kpi.replacement || kpi).id]
                                    .score,
                                ).label
                              }}
                            </span>
                          </div>
                          <div class="pvr-prior-review__comments">
                            {{
                              supervisorReviews[(kpi.replacement || kpi).id]
                                .comments || "—"
                            }}
                          </div>
                        </div>
                      </div>
                      <!-- Comments (full width) -->
                      <div class="pvr-kpi-card__comments">
                        <div class="pvr-comments-label">
                          Review Comments
                          <span
                            v-if="canEdit && queries.reviewer !== 'joint'"
                            class="pvr-comments-req"
                            >*</span
                          >
                        </div>
                        <textarea
                          v-if="canEdit"
                          class="pvr-comments-area"
                          :value="
                            kpiReview((kpi.replacement || kpi).id).comments
                          "
                          :placeholder="commentPlaceholder"
                          rows="3"
                          @input="
                            updateKpiComments(
                              (kpi.replacement || kpi).id,
                              $event.target.value,
                            )
                          "
                        ></textarea>
                        <div v-else class="pvr-comments-readonly">
                          {{
                            kpiReview((kpi.replacement || kpi).id).comments ||
                              "—"
                          }}
                        </div>
                      </div>
                      <!-- Card footer -->
                      <div v-if="canEdit" class="pvr-kpi-card__footer">
                        <div class="pvr-kpi-card__footer-left">
                          <template
                            v-if="isKpiComplete((kpi.replacement || kpi).id)"
                          >
                            <v-icon size="13" color="#059669"
                              >mdi-check-circle</v-icon
                            >
                            <span class="pvr-footer-ok">Review complete</span>
                          </template>
                          <template v-else>
                            <v-icon size="13" color="#f97316"
                              >mdi-alert-circle-outline</v-icon
                            >
                            <span class="pvr-footer-warn">{{
                              !kpiReview((kpi.replacement || kpi).id).score
                                ? "Select a score"
                                : "Add review comments"
                            }}</span>
                          </template>
                        </div>
                        <button
                          class="pvr-save-btn"
                          :class="{
                            'pvr-save-btn--active':
                              kpiReview((kpi.replacement || kpi).id).dirty &&
                              kpiReview((kpi.replacement || kpi).id).score,
                          }"
                          :disabled="
                            !kpiReview((kpi.replacement || kpi).id).dirty ||
                              !kpiReview((kpi.replacement || kpi).id).score ||
                              saving
                          "
                          @click="saveKpiReview((kpi.replacement || kpi).id)"
                        >
                          <v-icon size="12">mdi-content-save</v-icon>
                          Save
                        </button>
                      </div>
                    </div>
                  </div>
                </template>

                <!-- ── Case B: has sub-activities ──────────────────────── -->
                <template v-else>
                  <!-- Activity-level KPIs if any -->
                  <div
                    v-for="kpi in getKpis((act.replacement || act).id).filter(
                      (k) => k.adjustmentType !== 'drop',
                    )"
                    :key="'act-' + kpi.id"
                    class="pvr-kpi-slot"
                    :class="{
                      'pvr-kpi-slot--missing': !kpiReview(
                        (kpi.replacement || kpi).id,
                      ).score,
                    }"
                  >
                    <div
                      class="pvr-kpi-card"
                      :class="{
                        'pvr-kpi-card--complete': isKpiComplete(
                          (kpi.replacement || kpi).id,
                        ),
                        'pvr-kpi-card--readonly': reviewStatus === 'submitted',
                      }"
                    >
                      <div
                        v-if="
                          !kpiReview((kpi.replacement || kpi).id).score &&
                            reviewStatus !== 'submitted'
                        "
                        class="pvr-kpi-card__missing-badge"
                      >
                        <v-icon size="11" color="#dc2626"
                          >mdi-alert-circle</v-icon
                        >
                        Review required
                      </div>
                      <div class="pvr-kpi-card__context">
                        <span class="pvr-ctx pvr-ctx--obj">{{
                          (obj.replacement || obj).name
                        }}</span>
                        <v-icon size="11" color="#c4b5fd"
                          >mdi-chevron-right</v-icon
                        >
                        <span class="pvr-ctx pvr-ctx--act">{{
                          (act.replacement || act).name
                        }}</span>
                      </div>
                      <div class="pvr-kpi-card__row">
                        <div class="pvr-kpi-card__info">
                          <div class="pvr-kpi-badge">
                            <v-icon size="11" color="#6366f1"
                              >mdi-chart-bar</v-icon
                            >
                            KPI
                          </div>
                          <div class="pvr-kpi-card__kpi-name">
                            {{ (kpi.replacement || kpi).name }}
                          </div>
                          <div
                            v-if="(kpi.replacement || kpi).description"
                            class="pvr-kpi-card__kpi-desc"
                          >
                            {{ (kpi.replacement || kpi).description }}
                          </div>
                          <div
                            v-if="
                              getTargetForKpi((kpi.replacement || kpi).id) &&
                                getTargetForKpi((kpi.replacement || kpi).id)
                                  .adjustmentType !== 'drop'
                            "
                            class="pvr-kpi-card__target"
                          >
                            <v-icon size="12" color="#059669"
                              >mdi-bullseye-arrow</v-icon
                            >
                            <span class="pvr-kpi-card__target-label"
                              >Target:</span
                            >
                            <span class="pvr-kpi-card__target-name">{{
                              (
                                getTargetForKpi((kpi.replacement || kpi).id)
                                  .replacement ||
                                getTargetForKpi((kpi.replacement || kpi).id)
                              ).name
                            }}</span>
                          </div>
