                    <span class="pvr-prior-review__title">Self Assessment</span>
                    <span
                      class="pvr-prior-review__score"
                      :style="{
                        color: scoreOption(selfReviews[comp.id].score).color,
                        background: scoreOption(selfReviews[comp.id].score).bg,
                      }"
                    >
                      Score: {{ selfReviews[comp.id].score }} &mdash;
                      {{ scoreOption(selfReviews[comp.id].score).label }}
                    </span>
                  </div>
                  <div class="pvr-prior-review__comments">
                    {{ selfReviews[comp.id].comments || "—" }}
                  </div>
                </div>
                <div
                  v-if="reviewerCode === 'joint' && supervisorReviews[comp.id]"
                  class="pvr-prior-review pvr-prior-review--supervisor"
                >
                  <div class="pvr-prior-review__header">
                    <v-icon size="13" color="#5eead4"
                      >mdi-clipboard-account</v-icon
                    >
                    <span class="pvr-prior-review__title"
                      >Supervisor Evaluation</span
                    >
                    <span
                      class="pvr-prior-review__score"
                      :style="{
                        color: scoreOption(supervisorReviews[comp.id].score)
                          .color,
                        background: scoreOption(
                          supervisorReviews[comp.id].score,
                        ).bg,
                      }"
                    >
                      Score: {{ supervisorReviews[comp.id].score }} &mdash;
                      {{ scoreOption(supervisorReviews[comp.id].score).label }}
                    </span>
                  </div>
                  <div class="pvr-prior-review__comments">
                    {{ supervisorReviews[comp.id].comments || "—" }}
                  </div>
                </div>
              </div>

              <!-- Comments — optional for competencies -->
              <div class="pvr-kpi-card__comments">
                <div class="pvr-comments-label">
                  Review Comments
                  <span class="pvr-comments-optional">(optional)</span>
                </div>
                <textarea
                  v-if="canEdit && !hideReview"
                  class="pvr-comments-area"
                  :value="kpiReview(comp.id).comments"
                  :placeholder="commentPlaceholder"
                  rows="3"
                  @input="updateKpiComments(comp.id, $event.target.value)"
                ></textarea>
                <div v-else-if="!hideReview" class="pvr-comments-readonly">
                  {{ kpiReview(comp.id).comments || "—" }}
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- ── Sticky action bar ──────────────────────────────────────── -->
        <div
          class="pvr-action-bar"
          v-if="reviewStatus !== 'submitted' && canEdit"
        >
          <div class="pvr-action-bar__left">
            <div class="pvr-action-bar__track">
              <div
                class="pvr-action-bar__fill"
                :class="
                  completionPercent === 100
                    ? 'pvr-action-bar__fill--done'
                    : 'pvr-action-bar__fill--going'
                "
                :style="{ width: completionPercent + '%' }"
              ></div>
            </div>
            <span class="pvr-action-bar__label"
              >{{ reviewedCount }}/{{ totalKpisToReview }} reviews
              complete</span
            >
          </div>
          <div class="pvr-action-bar__right" v-if="canEdit">
            <button
              class="pvr-btn pvr-btn--ghost"
              :disabled="saving || !hasDirtyReviews"
              @click="save('draft')"
            >
              <v-icon left size="14">mdi-content-save-outline</v-icon>
              Save Draft
            </button>
            <button
              class="pvr-btn"
              :class="allKpisReviewed ? 'pvr-btn--primary' : 'pvr-btn--blocked'"
              :disabled="saving"
              @click="
                allKpisReviewed ? submitReview() : (showValidationBar = true)
              "
            >
              <v-icon left size="14">{{
                allKpisReviewed ? "mdi-send" : "mdi-alert-circle"
              }}</v-icon>
              {{
                allKpisReviewed
                  ? "Submit Review"
                  : missingCount +
                    " KPI" +
                    (missingCount !== 1 ? "s" : "") +
                    " Missing"
              }}
            </button>
          </div>
        </div>

        <!-- Submitted banner -->
        <div v-if="reviewStatus === 'submitted'" class="pvr-submitted-banner">
          <v-icon size="20" color="#059669">mdi-check-circle</v-icon>
          <div>
            <strong>Review submitted.</strong>
            This review has been finalized and cannot be modified.
          </div>
        </div>
      </template>
    </div>

    <!-- Submit dialog -->
    <v-dialog
      v-model="showSubmitDialog"
      max-width="440"
      content-class="pvr-dialog"
    >
      <div
        class="pvr-dialog__strip"
        :class="`pvr-dialog__strip--${reviewerCode}`"
      ></div>
      <div class="pvr-dialog__inner">
        <div class="pvr-dialog__head">
          <div
            class="pvr-dialog__icon"
            :class="`pvr-dialog__icon--${reviewerCode}`"
          >
            <v-icon color="white" size="20">mdi-send</v-icon>
          </div>
          <div>
            <div class="pvr-dialog__title">Submit {{ reviewerLabel }}</div>
            <div class="pvr-dialog__sub">
              FY {{ reviewWindowTargetFY }} · {{ periodDisplayLabel }}
            </div>
          </div>
          <button class="pvr-dialog__x" @click="showSubmitDialog = false">
            <v-icon size="16">mdi-close</v-icon>
          </button>
        </div>
        <div class="pvr-dialog__body">
          <p class="pvr-dialog__text">
            You are about to submit your
            <strong>{{ reviewerLabel }}</strong> for
            <strong>{{ performancePlan ? performancePlan.name : "" }}</strong
            >.
          </p>
          <div class="pvr-dialog__warning">
            <v-icon size="14" color="#d97706">mdi-alert-outline</v-icon>
            Once submitted, this review cannot be edited.
          </div>
        </div>
        <div class="pvr-dialog__foot">
          <button
            class="pvr-btn pvr-btn--ghost"
            @click="showSubmitDialog = false"
          >
            Cancel
          </button>
          <button
            class="pvr-btn pvr-btn--primary"
            :disabled="saving"
            @click="save('submitted')"
          >
            <v-icon left size="14">mdi-send</v-icon>
            Confirm Submit
          </button>
        </div>
      </div>
    </v-dialog>

    <!-- Snackbar -->
    <v-snackbar
      v-model="snackbar"
      :color="snackbarColor"
      top
      right
      :timeout="3500"
    >
      <v-icon left size="18">{{ snackbarIcon }}</v-icon>
      {{ snackbarMessage }}
      <template v-slot:action>
        <v-btn icon small @click="snackbar = false"
          ><v-icon size="16">mdi-close</v-icon></v-btn
        >
      </template>
    </v-snackbar>
  </div>
</template>

<script>
import generalMixin from "../../mixins/general";
import processQuestionnaire from "../../mixins/processQuestionnaire";

export default {
  name: "PerformanceReview",
  mixins: [generalMixin, processQuestionnaire],
  props: ["queries"],

  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/performance-review",
      fhir: {},
      profile:
        "http://ihris.org/fhir/StructureDefinition/performance-review-profile",
      loading: false,
      loadingText: "Loading plan\u2026",
      saving: false,
      currentFiscalYear: "",
      selectedPeriod: "aprilsept",

      performancePlan: null,
      staffName: "",
      objectives: [],
      activities: [],
      subActivities: [],
      kpis: [],
      targets: [],

      // { [kpiId]: { id, score, comments, dirty } }
      // Competency IDs are also stored here — same scoring mechanism reused
      kpiReviews: {},
      competencies: [],
      // Prior-stage reviews for reference display
      selfReviews: {},
      supervisorReviews: {},
      reviewStatus: "draft",
      windowClosedDismissed: false,

      expandedObjectives: {},
      showValidationBar: false,
      showSubmitDialog: false,

      snackbar: false,
      snackbarMessage: "",
      snackbarColor: "success",
      snackbarIcon: "mdi-check-circle",

      periods: [
        { code: "aprilsept", label: "Apr \u2013 Sep" },
        { code: "octmarch", label: "Oct \u2013 Mar" },
      ],
      reviewWindowOpen: null,
      reviewWindowTargetFY: "",
    };
  },

  computed: {
    canEdit() {
      if (this.reviewWindowOpen === false) return false;
      return (
        (this.queries.reviewer === "self" &&
          this.isOwner &&
          this.performancePlan?.selfReviewStatus !== "submitted") ||
        (this.queries.reviewer === "supervisor" &&
          this.isSupervisor &&
          this.performancePlan?.selfReviewStatus === "submitted" &&
          this.performancePlan?.supervisorReviewStatus !== "submitted") ||
        (this.queries.reviewer === "joint" &&
          this.isSupervisor &&
          this.performancePlan?.supervisorReviewStatus === "submitted" &&
          this.performancePlan?.jointReviewStatus !== "submitted")
      );
    },

    reviewWindowClosedMessage() {
      if (this.reviewWindowOpen !== false) return "";
      const windowName =
        this.selectedPeriod === "aprilsept"
          ? "Mid-Year Review (Semester 1)"
          : "Year-End Review (Semester 2)";
      return `The ${windowName} window is currently closed. Reviews can only be submitted during the configured window.`;
    },

    hideReview() {
      return (
        (!this.isOwner &&
          this.queries.reviewer === "self" &&
          this.performancePlan?.selfReviewStatus !== "submitted") ||
        (!this.isSupervisor &&
          this.queries.reviewer === "supervisor" &&
          this.performancePlan?.supervisorReviewStatus !== "submitted") ||
        (!this.isSupervisor &&
          this.queries.reviewer === "joint" &&
          this.performancePlan?.jointReviewStatus !== "submitted")
      );
    },
    supervisorCantReview() {
      return (
        this.queries.reviewer === "supervisor" &&
        this.performancePlan?.selfReviewStatus !== "submitted"
      );
    },
    jointCantReview() {
      return (
        this.queries.reviewer === "joint" &&
        this.performancePlan?.supervisorReviewStatus !== "submitted"
      );
    },
    hasDirtyReviews() {
      return Object.values(this.kpiReviews).some(
        (v) =>
          v.dirty && // Has been modified
          v.score && // Has a score selected
          v.comments && // Has comments
          v.comments.trim().length > 0, // Comments are not empty
      );
    },

    reviewerCode() {
      return this.queries.reviewer || "self";
    },

    reviewerLabel() {
      return (
        {
          self: "Self Assessment",
          supervisor: "Supervisor Evaluation",
          joint: "Joint Review",
        }[this.reviewerCode] || "Review"
      );
    },
    reviewerStage() {
      return { self: 1, supervisor: 2, joint: 3 }[this.reviewerCode] || 1;
    },
    reviewerIcon() {
      return {
        self: "mdi-account-edit",
        supervisor: "mdi-clipboard-account",
        joint: "mdi-handshake",
      }[this.reviewerCode];
    },
    reviewerIconColor() {
      return { self: "#f97316", supervisor: "#5eead4", joint: "#a5b4fc" }[
        this.reviewerCode
      ];
    },
    reviewerTypeLabel() {
      return (
        { self: "Self", supervisor: "Supervisor", joint: "Joint" }[
          this.reviewerCode
        ] || ""
      );
    },
    isOwnReview() {
      return (
        this.queries.practitioner === this.loggedInStaff.practitioner &&
        this.reviewerCode === "self"
      );
    },
    isOwner() {
      return this.queries.practitioner === this.loggedInStaff.practitioner;
    },
    isSupervisor() {
      return (
        this.practitionerProfile.supervisor.practitioner ===
        this.loggedInStaff.practitioner
      );
    },
    reviewPeriodNumber() {
      return this.selectedPeriod === "aprilsept" ? 1 : 2;
    },
    isAdjustmentApplied() {
      return this.performancePlan?.adjustmentStatus === "hod-approved";
    },
    periodDisplayLabel() {
      return this.selectedPeriod === "aprilsept"
        ? "April \u2013 September"
        : "October \u2013 March";
    },
    reviewStatusLabel() {
      return this.reviewStatus === "submitted" ? "Submitted" : "Draft";
    },
    commentPlaceholder() {
      const map = {
        self:
          "Describe your achievements, challenges encountered, and evidence for the score above\u2026",
        supervisor:
          "Provide evaluative feedback, observations, and developmental guidance\u2026",
        joint:
          "Enter the mutually agreed outcomes from the joint discussion\u2026",
      };
      return map[this.reviewerCode] || "Add your review comments\u2026";
    },

    scoreOptions() {
      return [
        {
          value: 4,
          label: "Exceeded Expectations",
          short: "Exceeded",
          color: "#059669",
          bg: "#ecfdf5",
          border: "#a7f3d0",
        },
        {
          value: 3,
          label: "Fully Met",
          short: "Fully Met",
          color: "#0d9488",
          bg: "#f0fdfa",
          border: "#99f6e4",
        },
        {
          value: 2,
          label: "Partially Met",
          short: "Partial",
          color: "#f97316",
          bg: "#fff7ed",
          border: "#fed7aa",
        },
        {
          value: 1,
          label: "Did Not Meet",
          short: "Not Met",
          color: "#ef4444",
          bg: "#fef2f2",
          border: "#fecaca",
        },
      ];
    },

    kpisToReview() {
      const result = [];
      // Walk top-down: visible objectives → visible activities → visible
      // sub-activities → KPIs. This guarantees counts match what the template
      // actually renders. Without this top-down walk, KPIs under a dropped
      // objective would inflate the total even though they're never rendered.
      for (const obj of this.objectives) {
        if (obj.adjustmentType === "drop") continue;
        const objId = (obj.replacement || obj).id;
        for (const act of this.getActivities(objId)) {
          // getActivities already filters drops, but the template additionally
          // hides activities whose effective state is dropped — keep this
          // explicit guard for safety even if getActivities changes.
          if (act.adjustmentType === "drop") continue;
          const actId = (act.replacement || act).id;
          for (const kpi of this.getKpis(actId)) {
            // Push the effective KPI (replacement when present) — reviews
            // are stored against that id, so downstream isKpiComplete(k.id)
            // resolves correctly without further unwrapping.
            result.push(kpi.replacement || kpi);
          }
          for (const sub of this.getSubActivities(actId)) {
            if (sub.adjustmentType === "drop") continue;
            const subId = (sub.replacement || sub).id;
            for (const kpi of this.getKpis(subId)) {
              result.push(kpi.replacement || kpi);
            }
          }
        }
      }
      // Competencies are scored the same way as KPIs — include them in totals
      for (const comp of this.competencies) result.push(comp);
      return result;
    },
    totalKpisToReview() {
      return this.kpisToReview.length;
    },
    reviewedCount() {
      // Delegate to isKpiComplete so competencies (comments optional) and
      // staff-goal KPIs (comments required) are handled consistently in one place.
      return this.kpisToReview.filter((k) => this.isKpiComplete(k.id)).length;
    },
    completionPercent() {
      if (!this.totalKpisToReview) return 0;
      return Math.round((this.reviewedCount / this.totalKpisToReview) * 100);
    },
    allKpisReviewed() {
      return (
        this.reviewedCount === this.totalKpisToReview &&
        this.totalKpisToReview > 0
      );
    },
    missingCount() {
      return this.totalKpisToReview - this.reviewedCount;
    },
  },

  watch: {
    selectedPeriod() {
      // Re-check the correct review window when the period selector changes
      this.loadReviewConfig();
    },
  },

  async mounted() {
    this.loading = true;
    await this.$nextTick();
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (v) => {
        if (!v) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        resolve();
      }, 15000);
    });
    if (this.queries.period) this.selectedPeriod = this.queries.period;
    try {
      let fy = await fetch("/site/leave/getFinancialYear");
      fy = await fy.json();
      this.currentFiscalYear = fy.year;
    } catch (e) {
      console.error(e);
    }
    await this.loadReviewConfig();
    await this.initialize();
    await this.markNotificationDone();
  },

  methods: {
    goHome() {
      window.location.href =
        "/custom/performance?path=/lesotho/components/performance";
    },
    async loadReviewConfig() {
      try {
        const [cfgRes, ovRes] = await Promise.all([
          fetch("/fhir/Parameters/performance-config").then((r) =>
            r.ok ? r.json() : null,
          ),
          fetch("/fhir/Parameters/performance-override-config").then((r) =>
            r.ok ? r.json() : null,
          ),
        ]);
        if (!cfgRes) return;
        const shift = (fy, d) => {
          const [s, e] = fy.split("/").map(Number);
          return `${s + d}/${e + d}`;
        };
        let todayDate = new Date();
        //this code is to simulate the review window being open or closed for testing purposes, by setting today's date to a fixed point in time depending on the selected period. In a real implementation, you would use the actual current date.
        // if (this.selectedPeriod === "aprilsept") {
        //   todayDate = new Date("2026-09-20");
        // } else {
        //   todayDate = new Date("2027-04-20");
        // }
        const todayMmDd =
          String(todayDate.getMonth() + 1).padStart(2, "0") +
          "-" +
          String(todayDate.getDate()).padStart(2, "0");
        const frac = (mmdd) => {
          if (!mmdd) return 0;
          const [mm, dd] = mmdd.split("-").map(Number);
          const mo = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
          return (
            (mo.slice(0, mm - 1).reduce((a, b) => a + b, 0) + dd - 1) / 365
          );
        };
        const inRange = (s, e) => {
          const t = frac(todayMmDd),
            sf = frac(s),
            ef = frac(e);
          return ef < sf ? t >= sf || t <= ef : t >= sf && t <= ef;
        };
        const overrides = {};
        for (const p of ovRes?.parameter || []) {
          const g = (n) =>
            (p.part || []).find((pt) => pt.name === n)?.valueString || "";
          overrides[p.name] = {
            fiscalYear: g("fiscal-year"),
            overrideEnd: g("override-end"),
            status: g("status"),
          };
        }
        // Semester 1 (aprilsept) reviews → mid-year-review window
        // Semester 2 (octmarch)  reviews → year-end-review window
        const windowKey =
          this.selectedPeriod === "aprilsept"
            ? "mid-year-review"
            : "year-end-review";
        const win = (cfgRes.parameter || []).find((p) => p.name === windowKey);
        if (!win) return;
        const g = (n) =>
          (win.part || []).find((pt) => pt.name === n)?.valueString || "";
        const ctx = g("fiscal-year-context");
        const delta = ctx === "next" ? 1 : ctx === "previous" ? -1 : 0;
        const targetFY = shift(this.currentFiscalYear, delta);
        this.reviewWindowTargetFY = targetFY;
        const baseOpen = inRange(g("start-date"), g("end-date"));
        const ov = overrides[windowKey];
        const ovActive =
          ov?.status === "active" &&
          ov.fiscalYear === targetFY &&
          new Date(ov.overrideEnd) >= todayDate;
        this.reviewWindowOpen = baseOpen || ovActive;
      } catch (e) {
        console.error("loadReviewConfig error", e);
        this.reviewWindowOpen = null;
      }
    },

    kpiReview(kpiId) {
      return this.kpiReviews[kpiId] || {};
    },
    scoreOption(score) {
      return (
        this.scoreOptions.find((o) => o.value === score) || this.scoreOptions[0]
      );
    },
    isKpiComplete(kpiId) {
      const r = this.kpiReviews[kpiId];
      if (!r) return false;

      const hasScore = r.score !== null && r.score !== undefined;

      // Competencies only need a score — comments are optional
      if (this.competencies.some((comp) => comp.id === kpiId)) {
        return hasScore;
      }

      // Staff-goal KPIs require both score and comments
      const hasComments =
        r.comments &&
        typeof r.comments === "string" &&
        r.comments !== "undefined" &&
        r.comments.trim().length > 0;

      return hasScore && hasComments;
    },
    selectKpiScore(kpiId, score) {
      const existing = this.kpiReviews[kpiId] || {};
      this.$set(this.kpiReviews, kpiId, { ...existing, score, dirty: true });
    },
    updateKpiComments(kpiId, val) {
      const existing = this.kpiReviews[kpiId] || {};
      this.$set(this.kpiReviews, kpiId, {
        ...existing,
        comments: val || "",
        dirty: true,
      });
    },

    // ── Init ─────────────────────────────────────────────────────────────
    async initialize() {
      this.loading = true;
      this.loadingText = "Loading performance plan\u2026";
      try {
        await this.loadStaffName();
        await this.loadPerformancePlan();
        if (this.performancePlan) {
          this.loadingText = "Loading objectives\u2026";
          await this.loadAllData();
          this.loadingText = "Loading existing reviews\u2026";
          await this.loadExistingReviews();
          await this.loadPriorReviews();
          if (this.objectives.length > 0 && !this.hideReview) {
            this.$set(this.expandedObjectives, this.objectives[0].id, true);
          }
        }
      } catch (e) {
        console.error(e);
        this.showSnackbar("Error loading data", "error");
      } finally {
        this.loading = false;
      }
    },

    async loadStaffName() {
      if (!this.queries.practitioner) return;
      try {
        const r = await fetch(
          `/fhir/Practitioner/${this.queries.practitioner}`,
        );
        const p = await r.json();
        const name = p.name?.[0];
        if (name) {
          const parts = [...(name.given || []), name.family].filter(Boolean);
          this.staffName = parts.join(" ");
        }
      } catch (e) {
        console.error(e);
      }
    },

    async loadPerformancePlan() {
      const practitioner = this.queries.practitioner;
      if (!practitioner) return;
      try {
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/performance-plan-profile",
          practitioner: `Practitioner/${practitioner}`,
          fiscalyear: this.reviewWindowTargetFY,
        });
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();
        if (b.entry?.length > 0) {
          this.performancePlan = this.extractPlanData(b.entry[0].resource);
          this.reviewStatus = this.performancePlan.reviewStatus || "draft";
        }
      } catch (e) {
        console.error(e);
      }
    },

    async loadAllData() {
      await this.loadObjectives();
      await this.loadActivities();
      await this.loadSubActivities();
      await this.loadKpis();
      await this.loadTargets();
      await this.loadCompetencies();
      await this.loadAdjustments();
    },

    async loadAdjustments() {
      // ⚠ INVARIANT: this function mutates this.objectives / this.activities /
      // this.subActivities / this.kpis / this.targets in place — it sets
      // adjustmentType on dropped goals, attaches `replacement` to replaced
      // goals, re-points parentIds, and removes replacement halves. If any
      // of those arrays is reloaded from FHIR without re-running this
      // function, the mid-year transformations are lost. The standard reload
      // path (loadAllData) already re-runs everything in order — keep that
      // discipline whenever you add a new reload path.
      if (!this.performancePlan) {
        this.adjustments = [];
        return;
      }
      const goals = [
        "objectives",
        "activities",
        "subActivities",
        "kpis",
        "targets",
      ];
      // ── Semester 1: show the original plan only ──────────────────────
      // Strip every goal added at mid-year (both fresh "add" goals and the
      // new half of a "replace"). The originals — including those that were
      // dropped or replaced later — remain visible because they were active
      // during S1 and must remain reviewable for that semester.
      if (this.reviewPeriodNumber === 1) {
        this.adjustments = [];
        for (const goal of goals) {
          this[goal] = this[goal].filter(
            (item) => item.lifecycleStatus !== "added-at-midyear",
          );
        }
        return;
      }

      // ── Semester 2 with no approved adjustment: show originals ───────
      if (!this.isAdjustmentApplied) {
        this.adjustments = [];
        return;
      }

      // ── Semester 2 with HOD-approved adjustment: apply the adjustment ─
      try {
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/goal-adjustment-profile",
          performanceplan: `Basic/${this.performancePlan.id}`,
          _count: 500,
        });
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();
        this.adjustments = (b.entry || []).map((e) => {
          const res = e.resource;
          return {
            id: res.id,
            adjustmentType:
              this.ext(res, "goal-adjustment-type")?.valueCoding?.code || "",
            oldGoalId:
              this.ext(res, "old-goal")?.valueReference?.reference?.split(
                "/",
              )[1] || null,
            supersededById:
              this.ext(
                res,
                "superseded-by-goal",
              )?.valueReference?.reference?.split("/")[1] || null,
            reason: this.ext(res, "reason")?.valueString || "",
          };
        });

        // ── Step 1: build a parentId remap (oldParentId → newParentId) ───
        // For every "replace" adjustment, the replacement goal becomes the
        // new parent. Children that still point at the old parent need to
        // be re-pointed at the replacement so the tree traversal works in S2.
        const parentRemap = {};
        for (const adj of this.adjustments) {
          if (
            adj.adjustmentType === "replace" &&
            adj.oldGoalId &&
            adj.supersededById
          ) {
            parentRemap[adj.oldGoalId] = adj.supersededById;
          }
        }

        // ── Step 2: walk goals top-down and apply the remap to children ──
        // Order matters — re-parent objectives' children first, then
        // activities' children, then sub-activities' children, etc. This
        // way a deeply nested replacement chain still resolves correctly.

        for (const goal of goals) {
          const replacements = [];
          for (const item of this[goal]) {
            // Re-parent: if this goal's parent has been replaced, point it
            // at the replacement and remember the original parent.
            if (item.parentId && parentRemap[item.parentId]) {
              item.oldParent = item.parentId;
              item.parentId = parentRemap[item.parentId];
            }

            if (
              item.lifecycleStatus === "original-active" ||
              item.lifecycleStatus === "added-at-midyear"
            ) {
              continue;
            }

            const adjustment = this.adjustments.find(
              (adj) => adj.oldGoalId === item.id,
            );
            item.adjustmentType = adjustment?.adjustmentType;
            if (
              !adjustment?.adjustmentType &&
              item.lifecycleStatus === "original-dropped"
            ) {
              item.adjustmentType = "drop";
            }
            if (adjustment?.adjustmentType === "replace") {
              const replacement = this[goal].find(
                (obj) => obj.id == adjustment.supersededById,
              );
              if (!replacement) {
                // The adjustment record references a replacement goal that
                // wasn't returned by the FHIR loaders (stale search index, a
                // missing reference, or it belongs to a different plan). The
                // template will fall back to showing the old goal as if
                // nothing was replaced — log this so the issue isn't silent.
                console.warn(
                  `[loadAdjustments] ${goal}: replacement goal ` +
                    `"${adjustment.supersededById}" referenced by adjustment ` +
                    `"${adjustment.id}" was not found in the loaded array. ` +
                    `The original goal "${item.id}" will be displayed unchanged.`,
                );
              }
              item.replacement = replacement;
              if (replacement) replacements.push(replacement);
            }
          }
          this[goal] = this[goal].filter((obj) => !replacements.includes(obj));
        }
      } catch (e) {
        console.error("loadAdjustments error", e);
        this.adjustments = [];
      }
    },

    async loadObjectives() {
      if (!this.performancePlan) return;
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-objective-profile",
        performanceplan: `Basic/${this.performancePlan.id}`,
      });
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.objectives = b.entry
        ? b.entry.map((e) => this.extractBasicData(e.resource))
        : [];
    },

    async loadActivities() {
      if (!this.objectives.length) {
        this.activities = [];
        return;
      }
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-activity-profile",
        parent: this.objectives.map((o) => o.id).join(","),
      });
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.activities = b.entry
        ? b.entry.map((e) => this.extractBasicData(e.resource))
        : [];
    },

    async loadSubActivities() {
      if (!this.activities.length) {
        this.subActivities = [];
        return;
      }
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-subactivity-profile",
        parent: this.activities.map((a) => a.id).join(","),
      });
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.subActivities = b.entry
        ? b.entry.map((e) => this.extractBasicData(e.resource))
        : [];
    },

    async loadKpis() {
      if (!this.activities.length && !this.subActivities.length) {
        this.kpis = [];
        return;
      }
      const ids = [
        ...this.activities.map((a) => a.id),
        ...this.subActivities.map((s) => s.id),
      ].join(",");
      const params = new URLSearchParams();
      params.append(
        "_profile",
        "http://ihris.org/fhir/StructureDefinition/performance-kpi-profile",
      );
      params.append("parent", ids);
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.kpis = b.entry
        ? b.entry.map((e) => this.extractBasicData(e.resource))
        : [];
    },

    async loadTargets() {
      if (!this.kpis.length) {
        this.targets = [];
        return;
      }
      const params = new URLSearchParams();
      params.append(
        "_profile",
        "http://ihris.org/fhir/StructureDefinition/performance-target-profile",
      );
      params.append("parent", this.kpis.map((k) => k.id).join(","));
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.targets = b.entry
        ? b.entry.map((e) => this.extractBasicData(e.resource))
        : [];
    },

    async loadCompetencies() {
      const grade = this.loggedInStaff?.grade;
      if (!grade) {
        this.competencies = [];
        return;
      }
      try {
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/competency-profile",
          salarygrade: "grade" + grade,
          _count: 200,
        });
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();
        this.competencies = (b.entry || []).map((e) => {
          const res = e.resource;
          return {
            id: res.id,
            name: this.ext(res, "ihris-basic-name")?.valueString || "",
            description: this.ext(res, "description")?.valueString || "",
            requirements:
              res.extension
                ?.filter((ex) => ex.url.includes("competency-requirements"))
                .map((ex) => ex.valueString)
                .filter(Boolean) || [],
          };
        });
      } catch (e) {
        console.error("Error loading competencies:", e);
        this.competencies = [];
      }
    },

    async loadExistingReviews() {
      if (!this.performancePlan) return;
      try {
        const params = new URLSearchParams();
        params.append(
          "_profile",
          "http://ihris.org/fhir/StructureDefinition/performance-review-profile",
        );
        params.append("performanceplan", `Basic/${this.performancePlan.id}`);
        params.append("performancereviewer", this.reviewerCode);
        params.append("performancereviewperiod", this.selectedPeriod);
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();
        if (b.entry) {
          const reviews = {};
          for (const e of b.entry) {
            const rev = this.extractReviewData(e.resource);
            if (rev.kpiId) {
              reviews[rev.kpiId] = {
                id: rev.id,
                score: rev.score,
                comments: rev?.comments || "",
                dirty: false,
              };
            }
          }
          this.kpiReviews = reviews;
        }
      } catch (e) {
        console.error("Error loading reviews:", e);
      }
    },

    async loadPriorReviews() {
      if (!this.performancePlan) return;
      const fetchReviewsByType = async (reviewerType) => {
        const params = new URLSearchParams();
        params.append(
          "_profile",
          "http://ihris.org/fhir/StructureDefinition/performance-review-profile",
        );
        params.append("performanceplan", `Basic/${this.performancePlan.id}`);
        params.append("performancereviewer", reviewerType);
        params.append("performancereviewperiod", this.selectedPeriod);
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();
        const reviews = {};
        if (b.entry) {
          for (const e of b.entry) {
            const rev = this.extractReviewData(e.resource);
            if (rev.kpiId) {
              reviews[rev.kpiId] = {
                score: rev.score,
                comments: rev.comments || "",
              };
            }
          }
        }
        return reviews;
      };
      try {
        if (this.reviewerCode === "supervisor") {
          this.selfReviews = await fetchReviewsByType("self");
        } else if (this.reviewerCode === "joint") {
          const [selfData, supData] = await Promise.all([
            fetchReviewsByType("self"),
            fetchReviewsByType("supervisor"),
          ]);
          this.selfReviews = selfData;
          this.supervisorReviews = supData;
        }
      } catch (e) {
        console.error("Error loading prior reviews:", e);
      }
    },

    // ── Extractors ────────────────────────────────────────────────────────
    ext(resource, url) {
      return resource.extension?.find((e) => e.url.includes(url));
    },
    extractPlanData(r) {
      return {
        id: r.id,
        name: this.ext(r, "ihris-basic-name")?.valueString || "",
        fiscalYear: this.ext(r, "fiscal-year")?.valueString || "",
        status: this.ext(r, "request-status")?.valueCoding?.code,
        adjustmentStatus:
          this.ext(r, "goal-adjustment-status")?.valueCoding?.code || null,
        reviewStatus: this.ext(
          r,
          this.queries.reviewer +
            "-period" +
            this.reviewPeriodNumber +
            "-annual-review-status",
        )?.valueCoding?.code,
        selfReviewStatus: this.ext(
          r,
          "self-period" + this.reviewPeriodNumber + "-annual-review-status",
        )?.valueCoding?.code,
        supervisorReviewStatus: this.ext(
          r,
          "supervisor-period" +
            this.reviewPeriodNumber +
            "-annual-review-status",
        )?.valueCoding?.code,
        jointReviewStatus: this.ext(
          r,
          "joint-period" + this.reviewPeriodNumber + "-annual-review-status",
        )?.valueCoding?.code,
      };
    },
    extractBasicData(r) {
      return {
        id: r.id,
        name: this.ext(r, "ihris-basic-name")?.valueString || "",
        description: this.ext(r, "description")?.valueString || "",
        parentId:
          this.ext(r, "parent")?.valueReference?.reference?.split("/")[1] ||
          null,
        lifecycleStatus:
          this.ext(r, "goal-lifecycle-status")?.valueCoding?.code ||
          "original-active",
      };
    },
    extractReviewData(r) {
      return {
        id: r.id,
        kpiId:
          this.ext(r, "parent")?.valueReference?.reference?.split("/")[1] ||
          null,
        score: this.ext(r, "score")?.valueInteger || null,
        comments: this.ext(r, "description")?.valueString || "",
      };
    },

    // ── Data helpers ──────────────────────────────────────────────────────
    // These filter out goals that were dropped during a HOD-approved mid-year
    // adjustment. The template additionally guards with v-if=... !== 'drop',
    // so dropped goals are doubly hidden. Importantly, count helpers
    // (objTotalKpis, objReviewedCount, kpisToReview) that rely on these
    // lookups now produce correct totals — dropped goals don't inflate counts.
    getActivities(objId) {
      return this.activities.filter(
        (a) => a.parentId === objId && a.adjustmentType !== "drop",
      );
    },
    getSubActivities(actId) {
      return this.subActivities.filter(
        (s) => s.parentId === actId && s.adjustmentType !== "drop",
      );
    },
    getKpis(parentId) {
      return this.kpis.filter(
        (k) => k.parentId === parentId && k.adjustmentType !== "drop",
      );
    },
    getTargetForKpi(kpiId) {
      return (
        this.targets.find(
          (t) => t.parentId === kpiId && t.adjustmentType !== "drop",
        ) || null
      );
    },
    objTotalKpis(objId) {
      let n = 0;
      for (const act of this.getActivities(objId)) {
        // Use the effective activity id (replacement if replaced, else self)
        // so that re-parented children are correctly counted.
        const actId = (act.replacement || act).id;
        n += this.getKpis(actId).length;
        for (const sub of this.getSubActivities(actId)) {
          const subId = (sub.replacement || sub).id;
          n += this.getKpis(subId).length;
        }
      }
      return n;
    },
    objReviewedCount(objId) {
      let n = 0;
      for (const act of this.getActivities(objId)) {
        const actId = (act.replacement || act).id;
        for (const kpi of this.getKpis(actId)) {
          // Reviews are stored against the replacement's id when a KPI is
          // replaced. Use the effective KPI id for completion checks.
          if (this.isKpiComplete((kpi.replacement || kpi).id)) n++;
        }
        for (const sub of this.getSubActivities(actId)) {
          const subId = (sub.replacement || sub).id;
          for (const kpi of this.getKpis(subId)) {
            if (this.isKpiComplete((kpi.replacement || kpi).id)) n++;
          }
        }
      }
      return n;
    },

    // ── Review save / submit ──────────────────────────────────────────────
    async saveKpiReview(kpiId) {
      const review = this.kpiReviews[kpiId];
      if (!review?.score) return;
    },

    async save(status) {
      this.saving = true;
      try {
        //filter only those modified
        const dirty = Object.entries(this.kpiReviews).filter(
          ([, v]) => v.dirty && v.score,
        );
        let reviews = [];
        for (let [kpiId, review] of dirty) {
          review.kpiId = kpiId;
          reviews.push(review);
        }
        this.fhir = {
          reviewStatus: status,
          planid: this.performancePlan.id,
          reviewerCode: this.reviewerCode,
          fiscalYear: this.reviewWindowTargetFY,
          reviews,
        };
        await this.processFHIR();
        if (status === "submitted") {
          this.showSubmitDialog = false;
        }
        await this.initialize();
        this.saving = false;
        if (status === "submitted") {
          this.showSnackbar("Review Submitted", "success");
        } else {
          this.showSnackbar("Draft saved", "success");
        }
      } catch (e) {
        if (status === "submitted") {
          this.showSubmitDialog = false;
        }
        this.saving = false;
        if (status === "submitted") {
          this.showSnackbar("Error submitting review", "error");
        } else {
          this.showSnackbar("Error saving draft", "error");
        }
      }
    },

    submitReview() {
      if (!this.allKpisReviewed) {
        this.showValidationBar = true;
        return;
      }
      this.showSubmitDialog = true;
    },

    // ── UI ────────────────────────────────────────────────────────────────
    toggleObjective(id) {
      this.$set(this.expandedObjectives, id, !this.expandedObjectives[id]);
    },
    headerBg(index) {
      const bgs = [
        "linear-gradient(135deg, #1e3a5f 0%, #1e40af 100%)",
        "linear-gradient(135deg, #0f4c5c 0%, #0e7490 100%)",
        "linear-gradient(135deg, #14532d 0%, #166534 100%)",
        "linear-gradient(135deg, #3b0764 0%, #6d28d9 100%)",
        "linear-gradient(135deg, #7c2d12 0%, #9a3412 100%)",
        "linear-gradient(135deg, #7f1d1d 0%, #991b1b 100%)",
      ];
      return bgs[index % bgs.length];
    },
    showSnackbar(message, color) {
      this.snackbarMessage = message;
      this.snackbarColor = color;
      const icons = {
        success: "mdi-check-circle",
        error: "mdi-alert-circle",
        warning: "mdi-alert",
        info: "mdi-information",
      };
      this.snackbarIcon = icons[color] || "mdi-information";
      this.snackbar = true;
    },
    async markNotificationDone() {
      let user = this.$store.state.user?.obj?.resource?.id;
      let task = await fetch(
        `/fhir/Basic?user=${user}&usertaskstatus=pending&usertaskcategory=performancereview&usertaskid=${this.performancePlan.id}&usertaskisnotification=true`,
      );
      let response = await task.json();
      if (response && response.entry && response.entry.length) {
        let taskDescr = response.entry[0].resource.extension.find((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/user-task-description"
          );
        });
        let statusIndex = taskDescr.extension.findIndex((ext) => {
          return ext.url === "status";
        });
        taskDescr.extension[statusIndex].valueCoding.code = "done";
        taskDescr.extension[statusIndex].valueCoding.display = "Done";

        fetch("/fhir/Basic/" + response.entry[0].resource.id, {
          method: "PUT",
          headers: {
            "Content-Type": "application/fhir+json",
            Accept: "application/fhir+json",
          },
          body: JSON.stringify(response.entry[0].resource),
        });
      }
    },
  },
};
</script>

