  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(255, 255, 255, 0.4);
}
.pvr-period-box__chips {
  display: flex;
  gap: 6px;
}
.pvr-period-chip {
  padding: 6px 14px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: rgba(255, 255, 255, 0.55);
  background: rgba(255, 255, 255, 0.07);
  transition: all 0.15s;
  font-family: "Sora", sans-serif;
}
.pvr-period-chip--active {
  background: rgba(255, 255, 255, 0.18);
  color: white;
  border-color: rgba(255, 255, 255, 0.35);
}
.pvr-period-chip--disabled {
  cursor: default;
  opacity: 0.5;
}

.pvr-progress-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}
.pvr-progress-ring {
  position: relative;
  flex-shrink: 0;
}
.pvr-progress-ring__text {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  align-items: baseline;
  gap: 1px;
}
.pvr-progress-ring__pct {
  font-size: 16px;
  font-weight: 800;
  color: white;
  line-height: 1;
}
.pvr-progress-ring__label {
  font-size: 10px;
  color: rgba(255, 255, 255, 0.6);
  font-weight: 600;
}
.pvr-progress-label {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.55);
  font-weight: 500;
  white-space: nowrap;
}

/* ── BODY ─────────────────────────────────────────────────────────── */
.pvr-body {
  max-width: 1200px;
  margin: 0 auto;
  padding: 28px 32px 80px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.pvr-empty-plan {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 80px;
  text-align: center;
  background: white;
  border-radius: 20px;
  border: 2px dashed #e7e5e4;
}
.pvr-empty-plan h3 {
  font-size: 18px;
  font-weight: 700;
  color: #1c1917;
  margin: 8px 0 0;
}
.pvr-empty-plan p {
  font-size: 13px;
  color: #a8a29e;
  line-height: 1.7;
  margin: 0 0 8px;
}

/* ── VALIDATION BAR ───────────────────────────────────────────────── */
.pvr-validation-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #fef2f2;
  border: 1.5px solid #fecaca;
  border-radius: 12px;
  padding: 12px 16px;
  font-size: 13px;
  color: #dc2626;
  font-weight: 500;
}
.pvr-validation-bar strong {
  font-weight: 700;
}
.pvr-validation-bar__close {
  margin-left: auto;
  width: 24px;
  height: 24px;
  border-radius: 6px;
  border: none;
  background: transparent;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s;
}
.pvr-validation-bar__close:hover {
  background: #fecaca;
}
.pvr-slide-enter-active,
.pvr-slide-leave-active {
  transition: all 0.2s;
  overflow: hidden;
}
.pvr-slide-enter,
.pvr-slide-leave-to {
  opacity: 0;
  max-height: 0;
  padding: 0;
}
.pvr-slide-enter-to,
.pvr-slide-leave {
  opacity: 1;
  max-height: 80px;
}

/* ── OBJECTIVE ────────────────────────────────────────────────────── */
.pvr-objective {
  border-radius: 18px;
  overflow: hidden;
  border: 1.5px solid #e7e5e4;
  background: white;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.04);
}
.pvr-objective__header {
  padding: 18px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  cursor: pointer;
}
.pvr-objective__header-left {
  display: flex;
  align-items: center;
  gap: 14px;
}
.pvr-objective__header-right {
  display: flex;
  align-items: center;
  gap: 16px;
}
.pvr-objective__num {
  font-family: "JetBrains Mono", monospace;
  font-size: 12px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.4);
  background: rgba(255, 255, 255, 0.1);
  padding: 3px 8px;
  border-radius: 6px;
  flex-shrink: 0;
}
.pvr-objective__title {
  font-size: 15px;
  font-weight: 700;
  color: white;
  letter-spacing: -0.01em;
}
.pvr-objective__desc {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.6);
  margin-top: 3px;
}

.pvr-obj-progress {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}
.pvr-obj-progress__count {
  font-size: 14px;
  font-weight: 800;
  color: white;
  font-family: "JetBrains Mono", monospace;
}
.pvr-obj-progress__label {
  font-size: 10px;
  color: rgba(255, 255, 255, 0.5);
  font-weight: 500;
}

.pvr-chevron {
  transition: transform 0.25s !important;
}
.pvr-rotate {
  transform: rotate(180deg) !important;
}

.pvr-objective__body {
  padding: 12px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ── ACTIVITY ─────────────────────────────────────────────────────── */
.pvr-activity {
  background: #fafaf8;
  border: 1.5px solid #e7e5e4;
  border-radius: 12px;
  overflow: hidden;
}
.pvr-activity__heading {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px 14px 10px;
  background: white;
  border-bottom: 1px solid #f5f5f4;
}
.pvr-activity__index {
  font-family: "JetBrains Mono", monospace;
  font-size: 10px;
  font-weight: 700;
  color: #a8a29e;
  background: #f5f5f4;
  padding: 3px 6px;
  border-radius: 5px;
  flex-shrink: 0;
  margin-top: 1px;
}
.pvr-activity__name {
  font-size: 13px;
  font-weight: 700;
  color: #1c1917;
  letter-spacing: -0.01em;
}
.pvr-activity__desc-small {
  font-size: 11px;
  color: #a8a29e;
  margin-top: 2px;
}

/* ── SUB-ACTIVITY ─────────────────────────────────────────────────── */
.pvr-subactivity {
  padding: 8px 12px 4px 16px;
}
.pvr-subactivity__heading {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 0 10px;
  border-bottom: 1px dashed #fed7aa;
  margin-bottom: 8px;
}
.pvr-subactivity__line {
  width: 14px;
  height: 1px;
  background: #f59e0b;
  flex-shrink: 0;
}
.pvr-subactivity__index {
  font-family: "JetBrains Mono", monospace;
  font-size: 10px;
  color: #d97706;
  background: #fef3c7;
  padding: 2px 6px;
  border-radius: 4px;
  flex-shrink: 0;
}
.pvr-subactivity__name {
  font-size: 12px;
  font-weight: 600;
  color: #78350f;
}

.pvr-no-kpis {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 12px 14px;
  font-size: 12px;
  color: #a8a29e;
}

/* ── KPI SLOT + CARD ──────────────────────────────────────────────── */
.pvr-kpi-slot {
  padding: 6px 12px 6px;
}
.pvr-kpi-slot--missing > .pvr-kpi-card {
  border-left: 3px solid #fecaca !important;
  border-radius: 0 14px 14px 0 !important;
}

.pvr-kpi-card {
  background: white;
  border: 1.5px solid #e7e5e4;
  border-radius: 14px;
  padding: 0;
  overflow: hidden;
  transition: box-shadow 0.2s, border-color 0.2s;
}
.pvr-kpi-card:hover:not(.pvr-kpi-card--readonly) {
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.07);
}
.pvr-kpi-card--complete {
  border-color: #bbf7d0 !important;
}
.pvr-kpi-card--readonly {
  background: #fafaf8;
}

.pvr-kpi-card__missing-badge {
  display: flex;
  align-items: center;
  gap: 5px;
  background: #fef2f2;
  border-bottom: 1px solid #fecaca;
  padding: 5px 14px;
  font-size: 11px;
  font-weight: 600;
  color: #dc2626;
}

/* Context breadcrumb */
.pvr-kpi-card__context {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  padding: 8px 14px 6px;
  border-bottom: 1px solid #f5f5f4;
  background: #fafaf8;
}
.pvr-ctx {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 2px 7px;
  border-radius: 4px;
}
.pvr-ctx--obj {
  background: #f5f3ff;
  color: #6d28d9;
}
.pvr-ctx--act {
  background: #f5f5f4;
  color: #57534e;
}
.pvr-ctx--sub {
  background: #fef3c7;
  color: #b45309;
}

/* KPI info + score row */
.pvr-kpi-card__row {
  display: flex;
  gap: 0;
  align-items: stretch;
}
.pvr-kpi-card__info {
  flex: 1;
  min-width: 0;
  padding: 14px 14px 12px;
  border-right: 1px solid #f5f5f4;
}
.pvr-kpi-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #6366f1;
  background: #eef2ff;
  border: 1px solid #c7d2fe;
  padding: 2px 7px;
  border-radius: 4px;
  margin-bottom: 7px;
}
.pvr-kpi-card__kpi-name {
  font-size: 14px;
  font-weight: 700;
  color: #1c1917;
  letter-spacing: -0.01em;
  margin-bottom: 4px;
  line-height: 1.3;
}
.pvr-kpi-card__kpi-desc {
  font-size: 12px;
  color: #78716c;
  line-height: 1.5;
  margin-bottom: 8px;
}

.pvr-kpi-card__target {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
  border-radius: 8px;
  padding: 5px 10px;
  font-size: 11px;
  color: #166534;
  flex-wrap: wrap;
}
.pvr-kpi-card__target-label {
  font-weight: 700;
}
.pvr-kpi-card__target-name {
  font-weight: 600;
}
.pvr-kpi-card__no-target {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  color: #a8a29e;
}

/* Score panel */
.pvr-kpi-card__score-panel {
  width: 240px;
  flex-shrink: 0;
  padding: 14px 14px 12px;
  display: flex;
  flex-direction: column;
}
.pvr-score-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #57534e;
  margin-bottom: 8px;
}
.pvr-score-btns {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.pvr-score-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  border-radius: 8px;
  border: 1.5px solid #e7e5e4;
  background: white;
  cursor: pointer;
  font-family: "Sora", sans-serif;
  transition: all 0.15s;
  text-align: left;
  width: 100%;
}
.pvr-score-btn:hover:not(:disabled) {
  border-color: #d6d3d1;
  background: #fafaf8;
}
.pvr-score-btn:disabled {
  cursor: default;
  opacity: 0.7;
}
.pvr-score-btn--selected {
  font-weight: 700;
}
.pvr-score-btn__num {
  font-family: "JetBrains Mono", monospace;
  font-size: 15px;
  font-weight: 700;
  min-width: 18px;
  line-height: 1;
}
.pvr-score-btn__short {
  font-size: 11px;
  font-weight: 600;
}

.pvr-score-selected {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 9px;
  border-radius: 7px;
  font-size: 11px;
  font-weight: 700;
  margin-top: 8px;
}

/* Comments (full width below the row) */
.pvr-kpi-card__comments {
  padding: 12px 14px;
  border-top: 1px solid #f5f5f4;
}
.pvr-comments-label {
  display: block;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #57534e;
  margin-bottom: 6px;
}
.pvr-comments-optional {
  font-size: 10px;
  color: #a8a29e;
  font-weight: 400;
  margin-left: 4px;
}
.pvr-comments-req {
  color: #f97316;
}
.pvr-comments-area {
  width: 100%;
  min-height: 70px;
  padding: 9px 12px;
  border: 1.5px solid #e7e5e4;
  border-radius: 9px;
  font-family: "Sora", sans-serif;
  font-size: 13px;
  line-height: 1.55;
  color: #1c1917;
  resize: vertical;
  transition: border-color 0.15s;
  outline: none;
  background: white;
  display: block;
}
.pvr-comments-area:focus {
  border-color: #6366f1;
}
.pvr-comments-readonly {
  background: #f8f7f5;
  border: 1.5px solid #f5f5f4;
  border-radius: 9px;
  padding: 9px 12px;
  font-size: 13px;
  color: #57534e;
  line-height: 1.55;
  min-height: 44px;
  white-space: pre-wrap;
}

/* Card footer */
.pvr-kpi-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  border-top: 1px solid #f5f5f4;
  background: #fafaf8;
}
.pvr-kpi-card__footer-left {
  display: flex;
  align-items: center;
  gap: 5px;
}
.pvr-footer-ok {
  font-size: 12px;
  font-weight: 600;
  color: #059669;
}
.pvr-footer-warn {
  font-size: 12px;
  font-weight: 600;
  color: #f97316;
}

.pvr-save-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 12px;
  border-radius: 7px;
  border: 1.5px solid #e7e5e4;
  background: white;
  cursor: pointer;
  font-size: 12px;
  font-weight: 700;
  font-family: "Sora", sans-serif;
  color: #78716c;
  transition: all 0.15s;
}
.pvr-save-btn--active {
  background: #eef2ff;
  border-color: #c7d2fe;
  color: #6366f1;
}
.pvr-save-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}
.pvr-save-btn--active:not(:disabled):hover {
  background: #e0e7ff;
}

/* ── ACTION BAR ───────────────────────────────────────────────────── */
.pvr-action-bar {
  position: sticky;
  bottom: 16px;
  z-index: 10;
  background: white;
  border: 1.5px solid #e7e5e4;
  border-radius: 14px;
  padding: 14px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
}
.pvr-action-bar__left {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
}
.pvr-action-bar__right {
  display: flex;
  gap: 8px;
}
.pvr-action-bar__track {
  flex: 1;
  max-width: 200px;
  height: 6px;
  background: #f5f5f4;
  border-radius: 3px;
  overflow: hidden;
}
.pvr-action-bar__fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.4s ease;
}
.pvr-action-bar__fill--going {
  background: linear-gradient(90deg, #f97316, #f59e0b);
}
.pvr-action-bar__fill--done {
  background: linear-gradient(90deg, #059669, #0d9488);
}
.pvr-action-bar__label {
  font-size: 12px;
  color: #78716c;
  font-weight: 600;
  white-space: nowrap;
}

/* ── SUBMITTED BANNER ─────────────────────────────────────────────── */
/* ── Competencies section ───────────────────────────────────────── */
.pvr-competencies-section {
  margin-top: 28px;
  border-top: 2.5px dashed #ede9fe;
  padding-top: 20px;
}
.pvr-competencies-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(135deg, #3b0764 0%, #6d28d9 100%);
  border-radius: 12px 12px 0 0;
  padding: 12px 18px;
  margin-bottom: 12px;
}
.pvr-competencies-header__left {
  display: flex;
  align-items: center;
}
.pvr-competencies-header__title {
  font-size: 13px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.01em;
}
.pvr-competencies-header__sub {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.6);
  margin-left: 6px;
}
.pvr-kpi-badge--competency {
  background: #ede9fe;
  color: #6d28d9;
  border-color: #ddd6fe;
}
.pvr-kpi-card--competency {
  border-left: 3px solid #7c3aed;
}
.pvr-comp-requirements {
  margin: 6px 0 0 16px;
  padding: 0;
  list-style: disc;
}
.pvr-comp-requirements li {
  font-size: 11px;
  color: #78716c;
  line-height: 1.5;
  margin-bottom: 2px;
}

.pvr-submitted-banner {
  display: flex;
  align-items: center;
  gap: 12px;
  background: #ecfdf5;
  border: 1.5px solid #a7f3d0;
  border-radius: 12px;
  padding: 16px 20px;
  font-size: 13px;
  color: #065f46;
}
.pvr-submitted-banner strong {
  font-weight: 700;
}

/* ── BUTTONS ──────────────────────────────────────────────────────── */
.pvr-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 9px 18px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 700;
  font-family: "Sora", sans-serif;
  cursor: pointer;
  border: none;
  transition: all 0.15s;
  letter-spacing: -0.01em;
  white-space: nowrap;
}
.pvr-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.pvr-btn--primary {
  background: #6366f1;
  color: white;
}
.pvr-btn--primary:hover:not(:disabled) {
  background: #4f46e5;
  box-shadow: 0 4px 16px rgba(99, 102, 241, 0.4);
}
.pvr-btn--ghost {
  background: white;
  color: #57534e;
  border: 1.5px solid #e7e5e4;
}
.pvr-btn--ghost:hover:not(:disabled) {
  background: #fafaf8;
}
.pvr-btn--outline {
  background: white;
  color: #1c1917;
  border: 1.5px solid #e7e5e4;
}
.pvr-btn--blocked {
  background: #fef2f2;
  color: #dc2626;
  border: 1.5px solid #fecaca;
  cursor: pointer;
}
.pvr-btn--blocked:hover {
  background: #fee2e2;
}

/* ── DIALOG ───────────────────────────────────────────────────────── */
.pvr-dialog {
  border-radius: 20px !important;
  overflow: hidden;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.18) !important;
}
.pvr-dialog__strip {
  height: 4px;
}
.pvr-dialog__strip--self {
  background: linear-gradient(90deg, #f97316, #ea580c);
}
.pvr-dialog__strip--supervisor {
  background: linear-gradient(90deg, #0d9488, #0891b2);
}
.pvr-dialog__strip--joint {
  background: linear-gradient(90deg, #6366f1, #4f46e5);
}
.pvr-dialog__inner {
  background: white;
}
.pvr-dialog__head {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 20px 22px 16px;
  border-bottom: 1px solid #f5f5f4;
  position: relative;
}
.pvr-dialog__icon {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.pvr-dialog__icon--self {
  background: linear-gradient(135deg, #f97316, #ea580c);
}
.pvr-dialog__icon--supervisor {
  background: linear-gradient(135deg, #0d9488, #0891b2);
}
.pvr-dialog__icon--joint {
  background: linear-gradient(135deg, #6366f1, #4f46e5);
}
.pvr-dialog__title {
  font-size: 16px;
  font-weight: 800;
  color: #1c1917;
  letter-spacing: -0.02em;
}
.pvr-dialog__sub {
  font-size: 12px;
  color: #a8a29e;
  margin-top: 1px;
}
.pvr-dialog__x {
  position: absolute;
  right: 18px;
  top: 50%;
  transform: translateY(-50%);
  width: 28px;
  height: 28px;
  border-radius: 7px;
  border: 1.5px solid #e7e5e4;
  background: white;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s;
}
.pvr-dialog__x:hover {
  background: #f5f5f4;
}
.pvr-dialog__body {
